static void petta_machine_invalidate_activation_frame(
        PettaMachineImpl *machine) {
    if (!machine)
        return;
    for (uint32_t index = 0u;
         index < PETTA_ACTIVATION_FRAME_CACHE_CAP; index++) {
        machine->activation_frames[index].equation_template = NULL;
        machine->activation_frames[index].activation_epoch = CETTA_FRAME_IDENTITY_NONE;
        machine->activation_frames[index].activation_first_entry = 0u;
        bindings_activation_view_free(
            &machine->activation_frames[index].frame);
    }
    machine->activation_frame_replacement = 0u;
}

static SymbolId petta_machine_reify_head(const PettaMachineImpl *machine) {
    return machine && machine->host.reify_head != SYMBOL_ID_NONE
        ? machine->host.reify_head
        : g_builtin_syms.collapse;
}

/* The host's materializer, `reify` where its profile offers it, and
 * `collapse`. */
static bool petta_machine_is_reify_head(
    const PettaMachineImpl *machine, SymbolId head) {
    return head == petta_machine_reify_head(machine) ||
        head == g_builtin_syms.collapse;
}

static CettaComputationPlan petta_machine_computation_plan(
    PettaMachineImpl *machine, const PettaGoal *goal, const PettaPlanNode *plan,
    Atom *expression, SymbolId head, PeTTaForm form, CettaExprLen nargs);

static Atom *petta_fresh_variable(PettaMachineImpl *machine);

/* HE's library definition of a collection function's call, its arguments
 * in place: each argument collected into a fresh variable in turn, the
 * aggregate of those, and its elements as alternatives. */
static Atom *petta_machine_he_library_stream_lower(
    PettaMachineImpl *machine, Atom *call, SymbolId aggregate) {
    Arena *heap = &machine->heap;
    CettaExprLen arity = call->expr.len - 1u;
    if (arity != 1u && arity != 2u)
        return NULL;
    Atom *collected[2] = {NULL, NULL};
    for (CettaExprLen index = 0u; index < arity; index++) {
        collected[index] = petta_fresh_variable(machine);
        if (!collected[index])
            return NULL;
    }
    Atom *result = petta_fresh_variable(machine);
    Atom *combined_elems[3] = {
        atom_symbol_id(heap, aggregate), collected[0], collected[1],
    };
    Atom *combined = result
        ? atom_expr(heap, combined_elems, arity + 1u) : NULL;
    Atom *emit = combined
        ? atom_expr2(heap, atom_symbol_id(heap, g_builtin_syms.superpose),
                     result) : NULL;
    Atom *body = emit ? atom_expr(heap, (Atom *[]){
        atom_symbol_id(heap, g_builtin_syms.let), result, combined, emit},
        4u) : NULL;
    for (CettaExprLen index = arity; body && index > 0u; index--) {
        Atom *collect = atom_expr2(
            heap, atom_symbol_id(heap, petta_machine_reify_head(machine)),
            call->expr.elems[index]);
        body = collect ? atom_expr(heap, (Atom *[]){
            atom_symbol_id(heap, g_builtin_syms.let), collected[index - 1u],
            collect, body}, 4u) : NULL;
    }
    return body;
}

static bool petta_machine_atom_is_reify_head(
    const PettaMachineImpl *machine, const Atom *atom) {
    return atom && atom->kind == ATOM_SYMBOL &&
        petta_machine_is_reify_head(machine, atom->sym_id);
}

/* Every machine-local shortcut reaches this same admission boundary before
 * calling the shared grounded dispatcher.  A host that does not model
 * profiles retains the historical unrestricted embedding behavior. */
static bool petta_machine_builtin_allowed(
        const PettaMachineImpl *machine, Atom *head) {
    if (!machine || !head || head->kind != ATOM_SYMBOL ||
        !machine->host.builtin_allowed) {
        return true;
    }
    return machine->host.builtin_allowed(
        machine->host.context, head->sym_id);
}

static PettaMachineBuiltinEquations petta_machine_builtin_equations_mode(
    PettaMachineImpl *machine, SymbolId head, CettaExprLen arity) {
    return machine && machine->host.builtin_equations && head != SYMBOL_ID_NONE
        ? machine->host.builtin_equations(
              machine->host.context, machine->space, head, arity)
        : PETTA_MACHINE_BUILTIN_EQUATIONS_NONE;
}

static bool petta_machine_builtin_equations_at_arity(
    PettaMachineImpl *machine, SymbolId head, CettaExprLen arity) {
    PettaMachineBuiltinEquations mode =
        petta_machine_builtin_equations_mode(machine, head, arity);
    return mode == PETTA_MACHINE_BUILTIN_EQUATIONS_APPEND ||
           mode == PETTA_MACHINE_BUILTIN_EQUATIONS_OWNED;
}

static bool petta_machine_builtin_equations(
    PettaMachineImpl *machine, Atom *expression, const PettaPlanNode *plan) {
    if (!expression || expression->kind != ATOM_EXPR ||
        expression->expr.len == 0u ||
        expression->expr.elems[0]->kind != ATOM_SYMBOL ||
        (plan && (plan->role == PETTA_PLAN_DATA ||
                  plan->role == PETTA_PLAN_VALUE)))
        return false;
    SymbolId head = expression->expr.elems[0]->sym_id;
    /* A dynamically selected binding form is an ordinary program function,
     * never a new occurrence of the source syntax it happens to name. */
    if (plan && plan->role == PETTA_PLAN_DYNAMIC_CALL &&
        petta_semantics_runtime_head(head) == PETTA_RUNTIME_HEAD_DATA)
        return false;
    return petta_machine_builtin_equations_at_arity(
        machine, head, expression->expr.len - 1u);
}

/* A grounded operation's outcome (grounded_call); false when the
 * operation is not allowed here or declines its arguments. */
static bool petta_machine_grounded_call(
        PettaMachineImpl *machine, Atom *head,
        Atom **arguments, uint32_t argument_count,
        CettaCallOutcome *outcome) {
    if (!machine || !petta_machine_builtin_allowed(machine, head))
        return false;
    if (machine->host.grounded_call)
        return machine->host.grounded_call(machine->host.context,
            machine->space, &machine->heap, head, arguments,
            argument_count, outcome);
    return grounded_call(
        &machine->heap, head, arguments, argument_count, outcome);
}

static bool petta_machine_declared_grounded(PettaMachineImpl *machine, SymbolId head) {
    return machine->host.forms_are_written_syntax &&
        !machine->host.structural_equation_heads &&
        machine->host.get_type && machine->host.type_calls &&
        head != SYMBOL_ID_NONE && is_grounded_op(head) &&
        petta_semantics_form(head) == PETTA_FORM_NONE &&
        space_head_declares_type(machine->space, head);
}

static bool petta_machine_try_plain_scalar_truth(
        PettaMachineImpl *machine, Atom *head,
        Atom **arguments, uint32_t argument_count, bool *truth_out) {
    if (head && head->kind == ATOM_SYMBOL &&
        petta_machine_declared_grounded(machine, head->sym_id))
        return false;
    if (head && head->kind == ATOM_SYMBOL &&
        petta_machine_builtin_equations_at_arity(
            machine, head->sym_id, argument_count))
        return false;
    /* A structural equality primitive may have correlated domains. Only
     * plain numbers establish that contract without asking the host. */
    if (machine->host.grounded_call && head &&
        head->sym_id == g_builtin_syms.op_eq &&
        (argument_count != 2u ||
         !arguments[0] || !arguments[1] ||
         arguments[0]->kind != ATOM_GROUNDED ||
         arguments[1]->kind != ATOM_GROUNDED ||
         (arguments[0]->ground.gkind != GV_INT &&
          arguments[0]->ground.gkind != GV_FLOAT) ||
         (arguments[1]->ground.gkind != GV_INT &&
          arguments[1]->ground.gkind != GV_FLOAT)))
        return false;
    return petta_machine_builtin_allowed(machine, head) &&
        grounded_try_plain_scalar_truth(
            head, arguments, argument_count, truth_out);
}

static bool petta_machine_try_plain_scalar_arithmetic(
        PettaMachineImpl *machine, Atom *head,
        Atom **arguments, uint32_t argument_count, Atom **value_out) {
    if (head && head->kind == ATOM_SYMBOL &&
        petta_machine_declared_grounded(machine, head->sym_id))
        return false;
    if (head && head->kind == ATOM_SYMBOL &&
        petta_machine_builtin_equations_at_arity(
            machine, head->sym_id, argument_count))
        return false;
    return petta_machine_builtin_allowed(machine, head) &&
        grounded_try_plain_scalar_arithmetic(
            &machine->heap, head, arguments, argument_count, value_out);
}

static bool petta_machine_type_pure_call_ready(
        PettaMachineImpl *machine, SymbolId head, CettaExprLen nargs, const PettaPlanNode *plan);
static Atom *petta_machine_boolean_value(
        PettaMachineImpl *machine, bool value);

/* A ground type-pure tree has no caller-visible substitution, so it reduces
 * on the heap without a contextual frame.  A nested call that is not
 * type-pure declines the whole tree and ordinary search evaluates it. */
static Atom *petta_machine_reduce_closed_scalar(
        PettaMachineImpl *machine, Atom *term, const PettaPlanNode *plan,
        unsigned depth, bool *nested) {
    if (!machine || !term || depth > 32u || atom_has_vars(term))
        return NULL;
    if (term->kind != ATOM_EXPR)
        return term;
    /* Substitution can put callable-looking data in a source variable's
     * position. The occurrence plan still owns whether that value runs. */
    if (plan && (plan->role == PETTA_PLAN_VALUE ||
                 plan->role == PETTA_PLAN_DATA))
        return term;
    if (plan && plan->child_count != term->expr.len)
        return NULL;
    if (term->expr.len < 2u || term->expr.len > 3u ||
        !term->expr.elems[0] ||
        term->expr.elems[0]->kind != ATOM_SYMBOL)
        return NULL;
    CettaExprLen nargs = term->expr.len - 1u;
    if (!petta_machine_type_pure_call_ready(
            machine, term->expr.elems[0]->sym_id, nargs, plan))
        return NULL;
    Atom *arguments[2] = {NULL, NULL};
    for (CettaExprLen index = 0u; index < nargs; index++) {
        Atom *argument = term->expr.elems[index + 1u];
        bool argument_nested = false;
        Atom *reduced = petta_machine_reduce_closed_scalar(
            machine, argument, petta_plan_child(plan, index + 1u),
            depth + 1u, &argument_nested);
        if (!reduced || reduced->kind != ATOM_GROUNDED)
            return NULL;
        if (argument->kind == ATOM_EXPR && nested)
            *nested = true;
        arguments[index] = reduced;
    }
    Atom *value = NULL;
    if (!petta_machine_try_plain_scalar_arithmetic(
            machine, term->expr.elems[0], arguments,
            (uint32_t)nargs, &value)) {
        bool truth = false;
        if (!petta_machine_try_plain_scalar_truth(
                machine, term->expr.elems[0], arguments,
                (uint32_t)nargs, &truth))
            return NULL;
        value = petta_machine_boolean_value(machine, truth);
    }
    return value;
}

static bool petta_machine_type_obligations_enabled(
    const PettaMachineImpl *machine) {
    return machine &&
        machine->host.analysis &&
        (machine->host.analysis->capabilities &
         PETTA_MACHINE_ANALYSIS_TYPE_OBLIGATIONS) != 0u;
}

static uint32_t petta_machine_analysis_policy(
    const PettaMachineImpl *machine) {
    return machine && machine->host.analysis &&
           machine->host.analysis->policy_identity
        ? machine->host.analysis->policy_identity(
              machine->host.context)
        : 0u;
}

static bool petta_machine_analysis_has_runtime_classifier(
    const PettaMachineImpl *machine, Atom *requirement) {
    return machine && machine->host.analysis &&
        machine->host.analysis->type_has_runtime_classifier &&
        machine->host.analysis->type_has_runtime_classifier(
            machine->host.context, machine->space, requirement);
}

static bool petta_machine_authority_token(
    PettaMachineImpl *machine, PettaMachineAuthorityToken *token) {
    if (!machine || !token)
        return false;
    *token = (PettaMachineAuthorityToken){0};
    const PettaAnalysisService *analysis = machine->host.analysis;
    if (!analysis)
        return true;
    PettaMachineAuthorityToken mutable = {0};
    if (analysis->mutable_authority_token &&
        !analysis->mutable_authority_token(
            machine->host.context, &mutable)) {
        return false;
    }
    return cetta_nik_direct_authority_v1_token(
        analysis->authority,
        petta_machine_analysis_policy(machine), &mutable, token);
}

static bool petta_machine_authority_token_eq(
    const PettaMachineAuthorityToken *left,
    const PettaMachineAuthorityToken *right) {
    if (!left || !right || left->length != right->length ||
        left->length > PETTA_MACHINE_AUTHORITY_WORD_CAPACITY) {
        return false;
    }
    if (left->length == 0u)
        return true;
    return cetta_nik_direct_authority_token_v1_equal(left, right);
}

static void petta_machine_invalidate_type_obligation_cache(
    PettaMachineImpl *machine) {
    if (!machine)
        return;
    machine->type_obligation_check_pending = true;
    machine->type_obligation_checked_read = (SpaceReadToken){0};
    machine->type_obligation_checked_epoch = 0u;
    machine->type_obligation_checked_policy = 0u;
    machine->type_obligation_checked_authority =
        (PettaMachineAuthorityToken){0};
    for (size_t index = 0u;
         index < machine->type_obligation_len; index++) {
        PettaTypeObligation *obligation =
            &machine->type_obligations[index];
        obligation->checked_value = NULL;
        obligation->checked_formal = NULL;
        obligation->checked_read = (SpaceReadToken){0};
        obligation->checked_epoch = 0u;
        obligation->checked_policy = 0u;
        obligation->checked_authority =
            (PettaMachineAuthorityToken){0};
        obligation->state = PETTA_TYPE_OBLIGATION_UNCHECKED;
    }
}

static uint64_t petta_machine_monotonic_ns(void) {
    struct timespec now;
    if (clock_gettime(CLOCK_MONOTONIC, &now) != 0)
        return 0u;
    return (uint64_t)now.tv_sec * UINT64_C(1000000000) +
           (uint64_t)now.tv_nsec;
}

static void petta_machine_add_u64(
    uint64_t *target, uint64_t amount) {
    if (!target)
        return;
    *target = UINT64_MAX - *target < amount
        ? UINT64_MAX : *target + amount;
}

static uint64_t petta_machine_arena_growth(
    const Arena *arena, size_t before) {
    size_t live = arena_accounted_live_bytes(arena);
    if (live <= before)
        return 0u;
    size_t growth = live - before;
    return growth > UINT64_MAX
        ? UINT64_MAX : (uint64_t)growth;
}

static bool petta_plan_open_template_admitted(
    const PettaPlanNode *plan) {
    return plan && plan->open_template_admitted;
}

static void petta_machine_note_binding_apply_environment(
    PettaMachineImpl *machine, const Bindings *bindings,
    CettaFrameIdentity identity, bool epoch_view) {
    if (!machine || !machine->host.measure_stats)
        return;
    size_t environment_entries = 0u;
    if (bindings && !bindings_current_binding_count(bindings, &environment_entries))
        environment_entries = SIZE_MAX;
    petta_machine_add_u64(
        &machine->stats.binding_apply_environment_entries,
        environment_entries > UINT64_MAX
            ? UINT64_MAX : (uint64_t)environment_entries);
    if (environment_entries >
        machine->stats.maximum_binding_apply_environment_entries) {
        machine->stats.maximum_binding_apply_environment_entries =
            environment_entries;
    }
    if (!epoch_view)
        return;
    machine->stats.binding_apply_epoch_calls++;
    size_t frame_entries = bindings_frame_binding_count(
        bindings, (BindingsFrameRef){.identity = identity});
    petta_machine_add_u64(
        &machine->stats.binding_apply_frame_entries,
        frame_entries > UINT64_MAX
            ? UINT64_MAX : (uint64_t)frame_entries);
    if (frame_entries >
        machine->stats.maximum_binding_apply_frame_entries) {
        machine->stats.maximum_binding_apply_frame_entries =
            frame_entries;
    }
}

static Atom *petta_machine_apply_bindings(
    PettaMachineImpl *machine, const Bindings *bindings,
    Arena *arena, Atom *atom) {
    if (!machine)
        return bindings_apply_if_vars(bindings, arena, atom);
    machine->stats.binding_apply_calls++;
    petta_machine_note_binding_apply_environment(
        machine, bindings, CETTA_FRAME_IDENTITY_NONE, false);
    bool rewrites = bindings_has_bound_values(bindings) && atom &&
        atom_has_vars(atom);
    if (rewrites)
        machine->stats.binding_apply_rewrites++;
    if (!machine->host.measure_stats)
        return bindings_apply_if_vars(bindings, arena, atom);
    size_t before = arena_accounted_live_bytes(arena);
    Atom *result = bindings_apply_if_vars(bindings, arena, atom);
    petta_machine_add_u64(
        &machine->stats.binding_apply_allocated_bytes,
        petta_machine_arena_growth(arena, before));
    return result;
}

static Atom *petta_machine_apply_bindings_epoch_since(
    PettaMachineImpl *machine, Bindings *bindings,
    Arena *arena, Atom *atom, CettaFrameIdentity epoch,
    uint32_t first_entry) {
    if (!machine)
        return bindings_apply_epoch_since(
            bindings, arena, atom, epoch, first_entry);
    machine->stats.binding_apply_calls++;
    petta_machine_note_binding_apply_environment(
        machine, bindings, epoch, true);
    bool rewrites = bindings_has_bound_values(bindings) && atom && atom_has_vars(atom);
    if (rewrites)
        machine->stats.binding_apply_rewrites++;
    if (!machine->host.measure_stats)
        return bindings_apply_epoch_since(
            bindings, arena, atom, epoch, first_entry);
    size_t before = arena_accounted_live_bytes(arena);
    Atom *result = bindings_apply_epoch_since(
        bindings, arena, atom, epoch, first_entry);
    petta_machine_add_u64(
        &machine->stats.binding_apply_allocated_bytes,
        petta_machine_arena_growth(arena, before));
    return result;
}

static Atom *petta_machine_apply_bindings_epoch_then_all(
    PettaMachineImpl *machine, Bindings *bindings,
    Arena *arena, Atom *atom, CettaFrameIdentity epoch,
    uint32_t first_entry) {
    if (!machine)
        return bindings_apply_epoch_then_all(
            bindings, arena, atom, epoch, first_entry);
    machine->stats.binding_apply_calls++;
    petta_machine_note_binding_apply_environment(
        machine, bindings, epoch, true);
    bool rewrites = bindings_has_bound_values(bindings) && atom && atom_has_vars(atom);
    if (rewrites)
        machine->stats.binding_apply_rewrites++;
    if (!machine->host.measure_stats)
        return bindings_apply_epoch_then_all(
            bindings, arena, atom, epoch, first_entry);
    size_t before = arena_accounted_live_bytes(arena);
    Atom *result = bindings_apply_epoch_then_all(
        bindings, arena, atom, epoch, first_entry);
    petta_machine_add_u64(
        &machine->stats.binding_apply_allocated_bytes,
        petta_machine_arena_growth(arena, before));
    return result;
}

/* PeTTa's existing root-only consumers retain this pointer convenience
 * wrapper; the binding-to-view semantics themselves live in match.c and are
 * shared with every evaluator dialect. */
static Atom *petta_machine_resolve_root(
        const Bindings *bindings, Atom *atom) {
    if (!atom || atom->kind != ATOM_VAR)
        return atom;
    Atom *resolved = NULL;
    return bindings_resolve_term_view_root_v1(
               (void *)bindings, atom, &resolved) ==
               CETTA_GSLT_TERM_VIEW_OK_V1
        ? resolved : NULL;
}

/* Root discriminators can borrow a materialized Atom only when resolution
 * does not erase a lexical context.  When the root is an open contextual
 * value, retain the original variable as its reference into the live
 * BindingValue store; the authoritative matcher will dereference it with
 * that context intact. */
static Atom *petta_machine_resolve_root_or_reference(
        const Bindings *bindings, Atom *atom) {
    if (!atom || atom->kind != ATOM_VAR)
        return atom;
    BindingValue value;
    if (!bindings_resolve_value_preview(
            (Bindings *)bindings, binding_value_from_atom(atom), &value) ||
        !value.skeleton) {
        return NULL;
    }
    return binding_value_is_contextual(value) &&
            atom_has_vars(value.skeleton)
        ? atom : value.skeleton;
}

typedef enum {
    PETTA_ATOM_COPY_QUERY,
    PETTA_ATOM_COPY_ANSWER,
    PETTA_ATOM_COPY_VISIBLE_VARIABLE,
    PETTA_ATOM_COPY_VISIBLE_VALUE,
    PETTA_ATOM_COPY_ERROR,
} PettaAtomCopyPurpose;

static void petta_machine_note_copy_purpose(
    PettaMachineStats *stats, PettaAtomCopyPurpose purpose,
    uint64_t allocated_bytes) {
    if (!stats)
        return;
    uint64_t *calls = NULL;
    uint64_t *bytes = NULL;
    switch (purpose) {
    case PETTA_ATOM_COPY_QUERY:
        calls = &stats->atom_copy_query_calls;
        bytes = &stats->atom_copy_query_allocated_bytes;
        break;
    case PETTA_ATOM_COPY_ANSWER:
        calls = &stats->atom_copy_answer_calls;
        bytes = &stats->atom_copy_answer_allocated_bytes;
        break;
    case PETTA_ATOM_COPY_VISIBLE_VARIABLE:
        calls = &stats->atom_copy_visible_variable_calls;
        bytes = &stats->atom_copy_visible_variable_allocated_bytes;
        break;
    case PETTA_ATOM_COPY_VISIBLE_VALUE:
        calls = &stats->atom_copy_visible_value_calls;
        bytes = &stats->atom_copy_visible_value_allocated_bytes;
        break;
    case PETTA_ATOM_COPY_ERROR:
        calls = &stats->atom_copy_error_calls;
        bytes = &stats->atom_copy_error_allocated_bytes;
        break;
    }
    petta_machine_add_u64(calls, 1u);
    petta_machine_add_u64(bytes, allocated_bytes);
}

static Atom *petta_machine_copy_atom_in(
    PettaMachineImpl *machine, Arena *arena, Atom *atom,
    PettaAtomCopyPurpose purpose, AtomDeepCopySession *session) {
    if (!machine)
        return session ? atom_deep_copy_session_copy(session, atom)
                       : purpose == PETTA_ATOM_COPY_ANSWER
                           ? atom_deep_copy_single(arena, atom)
                           : atom_deep_copy(arena, atom);
    machine->stats.atom_copy_calls++;
    size_t before = arena_accounted_live_bytes(arena);
    Atom *result = session ? atom_deep_copy_session_copy(session, atom)
                           : purpose == PETTA_ATOM_COPY_ANSWER
                               ? atom_deep_copy_single(arena, atom)
                               : atom_deep_copy(arena, atom);
    uint64_t allocated_bytes =
        petta_machine_arena_growth(arena, before);
    petta_machine_add_u64(
        &machine->stats.atom_copy_allocated_bytes, allocated_bytes);
    petta_machine_note_copy_purpose(
        &machine->stats, purpose, allocated_bytes);
    return result;
}

static Atom *petta_machine_copy_atom(
    PettaMachineImpl *machine, Arena *arena, Atom *atom,
    PettaAtomCopyPurpose purpose) {
    return petta_machine_copy_atom_in(machine, arena, atom, purpose, NULL);
}

static Atom *petta_machine_freshen_atom(
    PettaMachineImpl *machine, Atom *atom, CettaFrameIdentity epoch) {
    if (!machine)
        return NULL;
    machine->stats.atom_freshen_calls++;
    size_t before = arena_accounted_live_bytes(&machine->heap);
    Atom *result = atom_freshen_epoch(
        &machine->heap, atom, epoch);
    petta_machine_add_u64(
        &machine->stats.atom_freshen_allocated_bytes,
        petta_machine_arena_growth(&machine->heap, before));
    return result;
}

/* `atom` with its variables renamed into a fresh frame of `scope`, or NULL
 * when no identity is left for one: a capacity refusal, which the caller
 * reports as it reports any other. */
static Atom *petta_machine_freshen_in_scope(
    PettaMachineImpl *machine, Atom *atom, CettaFrameIdentityScope *scope) {
    CettaFrameIdentity epoch = CETTA_FRAME_IDENTITY_NONE;
    return cetta_frame_identity_scope_try(scope, &epoch)
        ? petta_machine_freshen_atom(machine, atom, epoch) : NULL;
}

static bool petta_machine_host_valid(const PettaMachineHost *host) {
    if (!host)
        return true;
    if (host->observation_contract &&
        !cetta_observation_contract_valid(
            *host->observation_contract)) {
        return false;
    }
    uint32_t known_analyses =
        PETTA_MACHINE_ANALYSIS_TYPE_OBLIGATIONS;
    const PettaAnalysisService *analysis = host->analysis;
    if (!analysis)
        return true;
    bool type_obligations =
        (analysis->capabilities &
         PETTA_MACHINE_ANALYSIS_TYPE_OBLIGATIONS) != 0u;
    return (analysis->capabilities & ~known_analyses) == 0u &&
        analysis->capabilities != 0u &&
        cetta_nik_direct_authority_v1_is_valid(
            analysis->authority) &&
        analysis->policy_identity &&
        analysis->mutable_authority_token &&
        (!type_obligations ||
         (analysis->judge_value &&
          analysis->type_has_runtime_classifier &&
          analysis->type_error_atom &&
          analysis->overload_error_atom &&
          analysis->reason_name &&
          analysis->validate_ready_call));
}

static bool petta_machine_host_can_evaluate(
        const PettaMachineHost *host) {
    return host && (host->evaluate || host->evaluate_planned);
}

static uint64_t petta_machine_fresh_instance_id(void) {
    uint64_t instance = atomic_fetch_add_explicit(
        &g_petta_machine_instance_counter, 1u,
        memory_order_relaxed);
    if (instance == 0u) {
        fputs("fatal: PeTTa machine identity space exhausted\n", stderr);
        abort();
    }
    return instance;
}

